mapper.select:
/* 最终查询：对合并后的结果按时间倒序 */ SELECT * FROM ( /* Part 1: 私聊列表 */ SELECT targetId, u.userNo AS targetName, 0 AS type, content AS lastMessage, /* 修复点：这里必须指定 private_chat.createTime，否则会和 user 表的字段冲突 */ private_chat.createTime AS lastMessageTime, unreadNum FROM ( SELECT /* 确定聊天对象ID */ CASE WHEN sender_id = #{userId} THEN receiver_id ELSE sender_id END AS targetId, /* 获取最新的一条消息内容 */ content, create_time AS createTime, /* 统计未读数 */ (SELECT COUNT(*) FROM chat_message cm2 WHERE cm2.sender_id = (CASE WHEN t1.sender_id = #{userId} THEN t1.receiver_id ELSE t1.sender_id END) AND cm2.receiver_id = #{userId} AND cm2.is_read = 0 ) AS unreadNum FROM chat_message t1 WHERE (sender_id = #{userId} OR receiver_id = #{userId}) AND type = 0 /* 取最新记录 */ AND id = ( SELECT MAX(id) FROM chat_message t2 WHERE ( (t2.sender_id = t1.sender_id AND t2.receiver_id = t1.receiver_id) OR (t2.sender_id = t1.receiver_id AND t2.receiver_id = t1.sender_id) ) AND t2.type = 0 ) ) AS private_chat LEFT JOIN user u ON private_chat.targetId = u.id
UNION ALL
/* Part 2: 群聊列表 */ SELECT t.id AS targetId, t.name AS targetName, 1 AS type, team_chat.content AS lastMessage, /* 这里你已经写对了 team_chat.createTime，所以 Part 2 没报错 */ team_chat.createTime AS lastMessageTime, 0 AS unreadNum FROM ( SELECT team_id, content, create_time AS createTime FROM chat_message t1 WHERE type = 1 AND team_id IN
#{teamId}
AND id = ( SELECT MAX(id) FROM chat_message t2 WHERE t2.team_id = t1.team_id AND t2.type = 1 ) ) AS team_chat LEFT JOIN team t ON team_chat.team_id = t.id ) AS combined_chat ORDER BY lastMessageTime DESC
